use flexion::{Candidate, Grammar, Known, Reading};
use std::borrow::Cow;

/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const NOM_M: u16 = 0;
    pub const NOM_F: u16 = 1;
    pub const NOM_N: u16 = 2;
    pub const NOM_PL: u16 = 3;
    pub const GEN_M: u16 = 4;
    pub const GEN_F: u16 = 5;
    pub const GEN_N: u16 = 6;
    pub const GEN_PL: u16 = 7;
    pub const DAT_M: u16 = 8;
    pub const DAT_F: u16 = 9;
    pub const DAT_N: u16 = 10;
    pub const DAT_PL: u16 = 11;
    pub const ACC_M: u16 = 12;
    pub const ACC_F: u16 = 13;
    pub const ACC_N: u16 = 14;
    pub const ACC_PL: u16 = 15;
}

/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Declension> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 16,
    lemma_cell: Some(0),
    capitalized: false,
    paradigms: Cow::Borrowed(&paradigms::DECLENSIONS),
    paradigm: rules::DECLENSION,
    relations: Cow::Borrowed(&relations::RELATIONS),
    feature: None,
    compound: None,
    prefixes: None,
    heads: flexion::Heads {
        least: None,
        words: Cow::Borrowed(&[]),
    },
    accent: None,
    laws: None,
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    marks: None,
    slots: Cow::Borrowed(&stems::SLOTS),
    tables: Cow::Borrowed(&stems::TABLES),
    irregular: irregular::IRREGULAR,
    smoothing: 2.0,
    sharpness: 4.0,
    trust: flexion::Trust {
        regular: 1.0,
        unsettled: 1.0,
        unattested: 1.0,
    },
};

/// A determiner form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A declined article, determiner or pronoun.
    Form(crate::Case, crate::Agreement),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        use crate::Agreement::*;
        use crate::Case::*;
        let cell = match self {
            Cell::Form(Nominative, Masculine) => cell::NOM_M,
            Cell::Form(Nominative, Feminine) => cell::NOM_F,
            Cell::Form(Nominative, Neuter) => cell::NOM_N,
            Cell::Form(Nominative, Plural) => cell::NOM_PL,
            Cell::Form(Genitive, Masculine) => cell::GEN_M,
            Cell::Form(Genitive, Feminine) => cell::GEN_F,
            Cell::Form(Genitive, Neuter) => cell::GEN_N,
            Cell::Form(Genitive, Plural) => cell::GEN_PL,
            Cell::Form(Dative, Masculine) => cell::DAT_M,
            Cell::Form(Dative, Feminine) => cell::DAT_F,
            Cell::Form(Dative, Neuter) => cell::DAT_N,
            Cell::Form(Dative, Plural) => cell::DAT_PL,
            Cell::Form(Accusative, Masculine) => cell::ACC_M,
            Cell::Form(Accusative, Feminine) => cell::ACC_F,
            Cell::Form(Accusative, Neuter) => cell::ACC_N,
            Cell::Form(Accusative, Plural) => cell::ACC_PL,
        };
        cell as usize
    }
}

impl From<(crate::Case, crate::Agreement)> for Cell {
    fn from((case, agreement): (crate::Case, crate::Agreement)) -> Self {
        Cell::Form(case, agreement)
    }
}

/// A determiner to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Determiner<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Determiner<'w> {
    /// The determiner `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Determiner {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
